28	  .board {
29	    display: grid;
30	    grid-template-columns: repeat(10, var(--cell));
31	    grid-template-rows: repeat(20, var(--cell));
32	    gap: 1px;
33	    padding: 1px;
34	    background: var(--grid);
35	    border: 2px solid #3a3f4d;
36	    border-radius: 4px;
37	    position: relative;
38	  }
