40	  .panel { display: flex; flex-direction: column; gap: 12px; min-width: 140px; }
41	  .box { background: var(--panel); border-radius: 6px; padding: 10px 14px; }
42	  .label { font-size: 12px; text-transform: uppercase; letter-spacing: .08em; color: var(--muted); }
43	  .value { font-size: 22px; font-weight: 600; font-variant-numeric: tabular-nums; }
