''','''  var LINE_SCORES = [0, 100, 300, 500, 800];
  // Locking rule: a gravity step that cannot move the piece down counts one tick of lock
  // delay; the piece locks on the LOCK_DELAY-th such tick. Moving left/right while resting
  // restarts the delay, at most MAX_LOCK_RESETS times per piece. Hard drop locks at once.
  var LOCK_DELAY = 2;
  var MAX_LOCK_RESETS = 3;
''')
rep('''  var current;      // { type, rot, row, col } or null''','''  var current;      // { type, rot, row, col, lockTicks, lockResets } or null''')
rep('''    var p = { type: type, rot: 0, row: SPAWN[type][0], col: SPAWN[type][1] };''','''    var p = { type: type, rot: 0, row: SPAWN[type][0], col: SPAWN[type][1], lockTicks: 0, lockResets: 0 };''')
rep('''    current.row += dr;
    current.col += dc;
    return true;
  }
''','''    current.row += dr;
    current.col += dc;
    if (dr > 0) current.lockTicks = 0;
    return true;
  }

  function isResting() {
    return !fits(current, current.rot, current.row + 1, current.col);
  }

  // Sideways move. If the piece was resting, this restarts its lock delay (capped per piece).
  function tryShift(dc) {
    if (!current) return false;
    var resting = isResting();
    if (!tryMove(0, dc)) return false;
    if (resting && current.lockResets < MAX_LOCK_RESETS) {
      current.lockResets++;
      current.lockTicks = 0;
    }
    return true;
  }
''')
