    for (var i = 0; i < kicks.length; i++) {
      var row = current.row + kicks[i][0];
      var col = current.col + kicks[i][1];
      if (fits(current, rot, row, col)) {
        current.rot = rot;
        current.row = row;
        current.col = col;
        return true;
      }
    }
    return false;
  }''','''  // Clockwise rotation. If the rotated shape does not fit in place, try sideways shifts only
  // (a vertical kick would let a resting piece climb and stay in the air). If nothing fits,
  // the piece is left untouched.
  function tryRotateCW() {
    if (!current) return false;
    var rot = (current.rot + 1) % 4;
    var kicks = [0, -1, 1, -2, 2];
    for (var i = 0; i < kicks.length; i++) {
      var col = current.col + kicks[i];
      if (fits(current, rot, current.row, col)) {
        current.rot = rot;
        current.col = col;
        return true;
      }
    }
    return false;
  }''')
rep('''    if (!tryMove(1, 0)) lockPiece();''','''    if (tryMove(1, 0)) return;
    current.lockTicks++;
    if (current.lockTicks >= LOCK_DELAY) lockPiece();''')
rep('''      case "left": tryMove(0, -1); break;
      case "right": tryMove(0, 1); break;''','''      case "left": tryShift(-1); break;
      case "right": tryShift(1); break;''')
rep('''      case "rotate": tryRotate(); break;''','''      case "rotateCW":
      case "rotate": tryRotateCW(); break;''')
rep('''    ArrowUp: "rotate",
    x: "rotate",
    X: "rotate",''','''    ArrowUp: "rotateCW",
    x: "rotateCW",
    X: "rotateCW",''')
open(p,'w').write(s)
